	@Test
	void throwingEndCallbackStillReturnsTheOrdinaryReaderPermit(@TempDir Path directory) throws Exception {
		long environment;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
			E(mdb_env_set_maxreaders(environment, TxnManager.POOL_SIZE));
			E(mdb_env_open(environment, directory.toString(), MDB_NOTLS | MDB_NOSYNC | MDB_NOMETASYNC, 0664));
		}
		TxnManager manager = new TxnManager(environment, TxnManager.Mode.ABORT);
		try {
			AtomicInteger ends = new AtomicInteger();
			IllegalStateException injected = new IllegalStateException("injected ordinary snapshot-end failure");
			manager.setSnapshotLifecycle(new TxnManager.SnapshotLifecycle() {
				@Override
				public void started(long transaction) {
				}

				@Override
				public void ended(long transaction) {
					if (ends.incrementAndGet() == 1) {
						throw injected;
					}
				}
			});
			int available = manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			TxnManager.Txn failed = manager.createReadTxnUntracked();
			assertThat(manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0)).isEqualTo(available - 1);
			assertThat(assertThrows(IllegalStateException.class, failed::close)).isSameAs(injected);
			assertThat(ends).as("one retirement attempt invokes ended exactly once").hasValue(1);
			boolean closedAfterFailure = failed.isClosed();
			boolean activeAfterFailure = failed.isNativeActive();
			int permitsAfterFailure = manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			// Fresh admission uses a new owned shell; never re-close the consumed pre-fix shell.
			try (TxnManager.Txn fresh = manager.createReadTxnUntracked()) {
				assertThat(fresh.isNativeActive()).isTrue();
				assertThat(fresh.isClosed()).isFalse();
			}
			assertThat(ends).as("fresh lease ends once without retrying the first lease callback").hasValue(2);
			SoftAssertions.assertSoftly(softly -> {
				softly.assertThat(closedAfterFailure)
						.as("native abort is irrevocable before callback failure")
						.isTrue();
				softly.assertThat(activeAfterFailure).isFalse();
				softly.assertThat(permitsAfterFailure)
						.as("failed outward close still returns its reader permit")
						.isEqualTo(available);
				softly.assertThat(manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0))
						.as("a later successful admission cannot leave the first permit stranded")
						.isEqualTo(available);
			});
		} finally {
			try {
				manager.close();
			} finally {
				mdb_env_close(environment);
			}
		}
	}

	@Test
	void throwingEndCallbackAfterParkingStillReturnsPermitAndAllowsRenewal(@TempDir Path directory)
			throws Exception {
		long environment;
		try (MemoryStack stack = MemoryStack.stackPush()) {
			PointerBuffer handle = stack.mallocPointer(1);
			E(mdb_env_create(handle));
			environment = handle.get(0);
			E(mdb_env_set_maxreaders(environment, TxnManager.POOL_SIZE));
			E(mdb_env_open(environment, directory.toString(), MDB_NOTLS | MDB_NOSYNC | MDB_NOMETASYNC, 0664));
		}
		TxnManager manager = new TxnManager(environment, TxnManager.Mode.RESET);
		try {
			AtomicInteger starts = new AtomicInteger();
			AtomicInteger ends = new AtomicInteger();
			IllegalStateException injected = new IllegalStateException("injected parked snapshot-end failure");
			manager.setSnapshotLifecycle(new TxnManager.SnapshotLifecycle() {
				@Override
				public void started(long transaction) {
					starts.incrementAndGet();
				}

				@Override
				public void ended(long transaction) {
					if (ends.incrementAndGet() == 1) {
						throw injected;
					}
				}
			});
			int available = manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			TxnManager.Txn failed = manager.createReadTxnUntracked();
			manager.reset(); // Untracked active readers become stale, not reset, until their public lease closes.
			assertThat(failed.isNativeActive()).isTrue();
			assertThat(ends).hasValue(0);
			assertThat(assertThrows(IllegalStateException.class, failed::close)).isSameAs(injected);
			assertThat(ends).hasValue(1);
			assertThat(failed.isIdle()).as("successful pool offer retains the native shell").isTrue();
			assertThat(failed.isClosed()).isFalse();
			assertThat(failed.isNativeActive()).as("native reset completed before its ended callback").isFalse();
			int permitsAfterFailure = manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			try (TxnManager.Txn renewed = manager.createReadTxnUntracked()) {
				assertThat(renewed).isSameAs(failed);
				assertThat(renewed.isNativeActive()).isTrue();
				assertThat(renewed.isClosed()).isFalse();
				assertThat(starts).hasValue(2);
			}
			int permitsAfterRenewal = manager.availableReadTxnSlots(TxnManager.POOL_SIZE, 0);
			assertThat(ends).as("outward pooled close does not end its retained native snapshot").hasValue(1);
			manager.close();
			assertThat(ends).as("shutdown ends the renewed native snapshot exactly once").hasValue(2);
			assertThat(manager.hasSnapshotLifecycle()).isFalse();
			SoftAssertions.assertSoftly(softly -> {
				softly.assertThat(permitsAfterFailure)
						.as("failed outward close still returns its parked lease permit")
						.isEqualTo(available);
				softly.assertThat(permitsAfterRenewal)
						.as("renewing the native shell must not strand an old permit")
						.isEqualTo(available);
			});
		} finally {
			try {
				manager.close();
			} finally {
				mdb_env_close(environment);
			}
		}
	}

